import { DevMessageType } from "@/types/dev";
import { moduleStore } from 'react-converter-code';
import pageStore from "@/store/page";
import file from "@/store/file";
import app from "@/store/app";
import language from '@/store/language'
import userStore from "@/store/userStore";
import plugins from "@/store/plugins";

class Store {
    
    channelKey = "dev-editor-preview";  // 频道名称
    myChannel: BroadcastChannel; // 频道

    // 发送消息
    postMessage = (key: DevMessageType, data: any = {}) => {
        this.myChannel.postMessage({
            key,
            data,
        })
    }

    /**
     * 发送全局环境
     */
    sendInit = async () => {
        const list = Object.values(pageStore.pages);
        console.log('appStore', app.getStore())
        for (const item of list) {
            if(!item.jsxRender){
                await item.getRenderText(); // 如果jsxRender 没有传递，那么立即渲染jsxRender 
            }
        }
        // 一次性发送全局配置
        this.postMessage(DevMessageType.资源传递, {
            pages: list.filter((o) => o.isPage).map((o) => { 
                return {
                    pageId: o.uid,
                    title: o.name,
                    content: o.getData(),
                    jsxRender: o.jsxRender,
                }
            }),
            modules: list.filter((o) => !o.isPage).map((o) => {
                return {
                    moduleId: o.uid,
                    title: o.name,
                    content: o.getData(),
                    jsxRender: o.jsxRender,
                }
            }),
            devToken: userStore.devToken,
            menus: pageStore.menus,
            fileStore: file.getStore(),
            appStore: app.getStore(),
            userStore: userStore.getStore(),
            languageStore: language.getStore(),
            pluginsStore: plugins.getStore(),
        })
    }

    // 监听信息
    onHandleMessage = (event) => {
        console.log('handleMessage', event)
        if(typeof event.data == "object"){
            const { key, data } = event.data;
            switch(key){
                case DevMessageType.环境监测:
                    // 通知页面接收到了通知信息
                    this.postMessage(DevMessageType.环境监测回应);
                    Promise.all([
                        pageStore.getOneMenu(),
                        plugins.init(),
                        language.reloadAppPlugins(),
                    ]).then(() => {
                        this.sendInit();
                    })
                break;
            }
        }
    };

    init = () => {
        // 创建一个名为 "my_channel" 的广播频道
        this.myChannel = new BroadcastChannel(this.channelKey);
        this.myChannel.addEventListener('message', this.onHandleMessage);
    }

    unInit = () => {
        this.myChannel.removeEventListener('message', this.onHandleMessage);
        this.myChannel.close();
    }
}


export default new Store;